// A migrated package's emitted JavaScript, for consumers that load no VibeLang
// plugin. The migrate flow commits each migrated package's emit under
// <package>/.vibelang/js/ and points the package's `default` export at it, so
// the `bun build` CLI and plain Node read JavaScript (opencode-32):
//
//   "./skill": { "types": "./src/skill.d.vibe.ts", "vibelang-source": "./src/skill.vibe",
//                "default": "./.vibelang/js/src/skill.js" }
//
// The loaders run the source instead: a module resolved to
// <package>/.vibelang/js/<path>.js follows its source map or migration receipt.
import { existsSync, readFileSync } from "node:fs"
import { basename, dirname, resolve, sep } from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { moduleDeclarationSource, nearestProject } from "./project.mjs"
import { jsxOf } from "./paths-imports.mjs"

export const emittedDirectory = ".vibelang/js"
const marker = `${sep}.vibelang${sep}js${sep}`

// A real source map is authoritative, including non-mirrored rootDir layouts.
// Migration emits without maps but writes an exact source receipt in its header.
function mappedSource(path, packageRoot) {
  let text
  try { text = readFileSync(path, "utf8") } catch { return {} }
  const directive = /(?:^|\r?\n)[ \t]*\/\/[#@] sourceMappingURL=([^\r\n]+)\s*$/.exec(text)?.[1].trim()
  if (directive) {
    try {
      let map, base
      if (directive.startsWith("data:")) {
        const comma = directive.indexOf(",")
        map = JSON.parse(directive.slice(0, comma).endsWith(";base64") ?
          Buffer.from(directive.slice(comma + 1), "base64").toString("utf8") : decodeURIComponent(directive.slice(comma + 1)))
        base = pathToFileURL(path)
      } else {
        base = new URL(directive, pathToFileURL(path))
        map = JSON.parse(readFileSync(base, "utf8"))
      }
      if (map.sources?.length !== 1) return { mapped: true }
      // TypeScript maps use filesystem spellings, which may contain # or %;
      // URL-style maps may encode those characters. Honor either convention.
      const raw = resolve(dirname(fileURLToPath(base)), map.sourceRoot || "", map.sources[0])
      if (existsSync(raw)) return { mapped: true, source: raw }
      const root = new URL((map.sourceRoot || "").replace(/([^/])$/, "$1/"), base)
      const url = new URL(map.sources[0], root)
      const source = url.protocol === "file:" ? fileURLToPath(url) : undefined
      return { mapped: true, source: source && existsSync(source) ? source : undefined }
    } catch { return { mapped: true } }
  }
  const header = /^\/\/ Generated by vibelang from (.+?)(?:; the migrate flow writes it again with each batch\.|\.)\r?$/.exec(text.replace(/^#![^\n]*\n/, "").split("\n", 1)[0])
  if (header) {
    const source = resolve(packageRoot, header[1])
    return { mapped: true, source: existsSync(source) ? source : undefined }
  }
  return {}
}

/** The source of a file in a package's emitted JavaScript, or undefined. */
export function sourceOfEmitted(path) {
  if (typeof path !== "string" || !/\.(?:[cm]?js|jsx)$/.test(path)) return undefined
  const at = path.lastIndexOf(marker)
  if (at < 0) return undefined
  const mapped = mappedSource(path, path.slice(0, at))
  if (mapped.mapped) {
    // A module declaration has its own exports, though its map names the
    // containing source. Loading that source would select the wrong module.
    if (mapped.source && moduleDeclarationSource(basename(path)) === basename(mapped.source)) return undefined
    return mapped.source
  }
  const extension = /\.(?:[cm]?js|jsx)$/.exec(path)[0]
  const stem = path.slice(0, at) + sep + path.slice(at + marker.length, -extension.length)
  const project = nearestProject(stem + ".vibe")
  const jsx = jsxOf(project)
  // With no receipt, accept only an unambiguous source that produces this
  // output name in the project's JSX mode. Never rank competing siblings.
  // No config retains legacy .jsx lookup for a standalone mirrored output.
  const preserve = typeof jsx === "string" && jsx.toLowerCase() === "preserve" || project === undefined && extension === ".jsx"
  const candidates = [".ts", ".tsx", ".vibe", ".vibex", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs"].filter(suffix => {
    const output = [".mts", ".mjs"].includes(suffix) ? ".mjs" :
      [".cts", ".cjs"].includes(suffix) ? ".cjs" :
      preserve && [".tsx", ".vibex", ".jsx"].includes(suffix) ? ".jsx" : ".js"
    return output === extension
  }).map(suffix => stem + suffix).filter(source => existsSync(source))
  return candidates.length === 1 ? candidates[0] : undefined
}

/**
 * The module Bun's runtime loads for an emitted file whose source is source: a
 * re-export of the source module. Bun's runtime calls no onResolve for an
 * import it resolves itself, so the emitted path stays, and re-exporting keeps
 * one instance of the source module for the package's own relative imports
 * and its consumers' package imports alike. A default is forwarded only when
 * the source actually exports one, and remains a live binding.
 */
export function reexportOf(source, hasDefault = false) {
  const name = JSON.stringify(source)
  return `export * from ${name}\n` + (hasDefault ? `export { default } from ${name}\n` : "")
}
